// BOOSTER COMBINER. Each Shelly adapter reports on bsf/hotwater/b1|b2/plug_state|plug_power. The dispatcher
// expects ONE hot-water plug, so it gets the SUM on the original topics: plug_state = either booster on,
// plug_power = their watts added. Its surplus (solar minus everything but the boosters) then never depends
// on Booster 2, so Booster 2 can never make it shed Booster 1. A booster not heard from for 150 s counts as
// off (its dead-man has switched it off by then). Booster readings are kept in flow context for the
// secondary dispatcher on this tab.
const FRESH_MS = 150000;
var m = /^bsf\/hotwater\/(b1|b2)\/plug_(state|power)$/.exec(msg.topic || '');
if (!m) return null;
var all = flow.get('boosters') || {};
var b = all[m[1]] || {};
var now = Date.now();
if (m[2] === 'state') { b.on = (msg.payload === true || msg.payload === 'true'); b.on_ts = now; }
else { var w = parseFloat(msg.payload); if (!isFinite(w)) return null; b.w = w; b.w_ts = now; }
all[m[1]] = b; flow.set('boosters', all);
var on = false, total = 0;
['b1', 'b2'].forEach(function (k) {
  var x = all[k];
  if (!x || !x.on_ts || now - x.on_ts > FRESH_MS || !x.on) return;
  on = true;
  if (x.w_ts && now - x.w_ts <= FRESH_MS) total += x.w;
});
return [[ { topic: 'bsf/hotwater/plug_state', payload: on }, { topic: 'bsf/hotwater/plug_power', payload: Math.round(total) } ]];

// HOT WATER 2 — SECONDARY DISPATCHER. Booster 2 only ever runs alongside Booster 1, and sheds first.
// Reads the main dispatcher's status (bsf/hotwater/status, every 10 s) and the boosters' own readings.
//   spare = surplus_now - booster1_W - booster2_W   (surplus_now already excludes both boosters)
// Hard OFF, at once: dispatcher status older than 60 s or inputs stale · outside the daytime window ·
//   Booster 1 off · SOC < soc_off · total load > max_total_w · battery discharging > batt_trip_w.
// Soft OFF, after sustain_off_ms: not curtailed and spare <= surplus_off_w (the panels can't cover both).
// ON, after sustain_on_ms: Booster 1 on for >= min_primary_on_ms, Booster 2 off for >= min_off_ms,
//   SOC >= soc_on, total load + Booster 2 <= max_total_w, and (spare >= surplus_on_w OR curtailed).
// Outside the window it re-sends OFF every 5 min, like the main lockout loop.
const C = __HW2_CFG__;
var now = Date.now();
if (msg.topic === 'bsf/hotwater/status') {
  var p = msg.payload;
  if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
  context.set('S', p); context.set('S_ts', now);
} else if (msg.topic !== 'tick') return null;

var S = context.get('S'), S_ts = context.get('S_ts') || 0;
var all = flow.get('boosters') || {};
function watts(k) {
  var x = all[k];
  if (!x || !x.on || !x.on_ts || now - x.on_ts > 150000) return 0;
  return (x.w_ts && now - x.w_ts <= 150000) ? x.w : 0;
}
var p1 = watts('b1'), p2 = watts('b2');
var on2 = context.get('on2') === true;
var onSince = context.get('onSince') || null, offSince = context.get('offSince') || null;
var offAt = context.get('offAt') || 0, onAt = context.get('onAt') || 0, lastOffSent = context.get('lastOffSent') || 0;
var primaryOnSince = context.get('primaryOnSince') || null;

function iso() { return new Date().toISOString(); }
function cmd(on) { return { payload: { dps: '1', set: on } }; }
function log(ev, extra) { return { topic: 'bsf/hotwater/log', payload: Object.assign({ ts: iso(), event: ev, source: 'booster2' }, extra || {}) }; }

var hard = null;
if (!S || now - S_ts > 60000) hard = 'dispatcher status stale';
else if (S.stale && S.stale.length) hard = 'inputs stale: ' + S.stale.join(',');
else if (S.mode !== 'DISPATCH') hard = 'outside the daytime window';
else if (S.hwState !== 'on') hard = 'Booster 1 off';
else if (!(S.soc >= C.soc_off)) hard = 'SOC ' + S.soc + '% < ' + C.soc_off + '%';
else if (S.ac_load > C.max_total_w) hard = 'total load ' + Math.round(S.ac_load) + ' W > ' + C.max_total_w + ' W';
else if (S.batt_power < -C.batt_trip_w) hard = 'battery discharging ' + Math.round(-S.batt_power) + ' W';

if (S && S.hwState === 'on') { if (!primaryOnSince) { primaryOnSince = now; context.set('primaryOnSince', primaryOnSince); } }
else { primaryOnSince = null; context.set('primaryOnSince', null); }

var spare = S ? Math.round(num(S.surplus_now) - p1 - p2) : null;
function num(x) { return (typeof x === 'number' && isFinite(x)) ? x : 0; }
var curtailed = !!(S && S.curtailed);
var status = { topic: 'bsf/hotwater2/status', payload: { ts: iso(), on: on2, spare: spare, b1_w: Math.round(p1), b2_w: Math.round(p2),
  curtailed: curtailed, hold: hard, soc: S ? S.soc : null, ac_load: S ? S.ac_load : null } };

function turnOff(ev, reason) {
  context.set('on2', false); context.set('offAt', now); context.set('onSince', null); context.set('offSince', null);
  context.set('lastOffSent', now);
  status.payload.on = false;
  return [cmd(false), log(ev, { reason: reason, soc: S ? S.soc : null, surplus: spare, ac: S ? S.ac_load : null, batt_power: S ? S.batt_power : null, on_minutes: onAt ? +((now - onAt) / 60000).toFixed(1) : null }), status];
}

if (on2) {
  if (hard) return turnOff('off_b2_' + (hard.indexOf('Booster 1') === 0 ? 'primary_off' : 'safety'), hard);
  if (!curtailed && spare <= C.surplus_off_w) {
    if (!offSince) { offSince = now; context.set('offSince', now); }
    if (now - offSince >= C.sustain_off_ms) return turnOff('off_b2_surplus', 'spare ' + spare + ' W <= ' + C.surplus_off_w + ' W for ' + C.sustain_off_ms / 1000 + ' s');
  } else if (offSince) context.set('offSince', null);
  return [null, null, status];
}

// Booster 2 is off
if (hard) {
  if (onSince) context.set('onSince', null);
  if (S && S.mode !== 'DISPATCH' && now - lastOffSent >= 300000) { context.set('lastOffSent', now); return [cmd(false), null, status]; }
  return [null, null, status];
}
var ok = primaryOnSince && (now - primaryOnSince >= C.min_primary_on_ms)
      && (now - offAt >= C.min_off_ms)
      && S.soc >= C.soc_on
      && (S.ac_load + C.rated_w <= C.max_total_w)
      && (spare >= C.surplus_on_w || curtailed);
if (!ok) { if (onSince) context.set('onSince', null); return [null, null, status]; }
if (!onSince) { onSince = now; context.set('onSince', now); }
if (now - onSince < C.sustain_on_ms) return [null, null, status];
context.set('on2', true); context.set('onAt', now); context.set('onSince', null); context.set('offSince', null);
status.payload.on = true;
return [cmd(true), log(curtailed ? 'on_b2_curtailment' : 'on_b2_surplus', { soc: S.soc, surplus: spare, ac: S.ac_load, batt_power: S.batt_power, curtailed: curtailed }), status];
